4	// The "add a job" form. Owns its own draft state (CLAUDE.md — features own their state) and does
5	// the create itself; on success it hands the new project back to the list through onCreated.
6	export function ProjectForm({
7	  clients,
8	  onCreated,
9	}: {
10	  clients: Client[];
11	  onCreated: (project: Project) => void;
12	}) {
13	  const [name, setName] = useState('');
14	  const [clientId, setClientId] = useState('');
15	  const [status, setStatus] = useState<ProjectStatus>('ACTIVE');
16	
17	  // Default to the first client once the list arrives, without clobbering a chosen value.
18	  useEffect(() => {
19	    setClientId((prev) => prev || (clients[0] ? String(clients[0].id) : ''));
20	  }, [clients]);
21	
22	  async function onSubmit(e: React.FormEvent) {
23	    e.preventDefault();
24	    const res = await fetch('/api/projects', {
25	      method: 'POST',
26	      headers: { 'Content-Type': 'application/json' },
27	      body: JSON.stringify({ name, clientId: Number(clientId), status }),
28	    });
29	    if (res.ok) {
30	      onCreated(await res.json());
31	      setName('');
32	    }
33	  }
34	
35	  return (
36	    <form data-testid="project-form" onSubmit={onSubmit}>
37	      <input
38	        data-testid="project-form-name"
39	        placeholder="Name"
40	        value={name}
41	        onChange={(e) => setName(e.target.value)}
42	      />
43	      <select
44	        data-testid="project-form-client"
45	        value={clientId}
46	        onChange={(e) => setClientId(e.target.value)}
47	      >
48	        {clients.map((c) => (
49	          <option key={c.id} value={c.id}>
50	            {c.name}
51	          </option>
52	        ))}
53	      </select>
54	      <select
