        if (status.isEmpty()) {
            status = "ACTIVE";
        }
        if (!STATUSES.contains(status)) {
            throw new HttpException(HttpStatus.BAD_REQUEST, "Unknown project status: " + status);
        }
        response.send(repository.create(name, body.getClientId(), status));
    }
}

